import { options, icon } from '../ui.js';
export default function settings({state,ui}) {
 if(!ui.settingsSection)return `<h2 class="settings-title">הגדרות מערכת</h2><div class="settings-tiles">${[['users','משתמשים','העדפות עבודה וצוות מטפל','people'],['accounts','לקוחות ולידים','הגדרות קליטה וניהול לקוחות','building'],['sales','מכירות','תהליך עבודה ושלבי טיפול','board'],['tasks','משימות','הגדרות תהליך חדש','list'],['calendar','יומן','פגישות ואירועים','calendar'],['reports','דוחות','עמודות וסינון נתונים','document'],['knowledge','מרכז ידע','מדריכים ומידע לצוות','book'],['document','מסמכים','שורות, מחירים והנחות','document']].map(([id,title,desc,i])=>`<button class="settings-tile" data-action="settings-section" data-section="${id}">${icon(i)}<strong>${title}</strong><span>${desc}</span></button>`).join('')}</div>`;
 return `<div class="settings-layout"><aside class="settings-nav"><button class="outline" data-action="settings-home">חזרה להגדרות ←</button><h2>הגדרות משתמשים</h2><span class="selected">העדפות עבודה</span><a href="#import">קליטת נתונים</a><a href="#reports">דוחות</a></aside><form data-form="settings" class="card settings-form"><h2 class="panel-caption">העדפות עבודה</h2><div class="form-grid"><label class="field"><span>צוות ברירת מחדל לרשומות חדשות</span><select name="owner">${options(['צוות 1','צוות 2','צוות 3'],state.settings.owner)}</select></label><div><label class="checks"><input type="checkbox" name="notifications" ${state.settings.notifications?'checked':''}>הצגת הודעות אישור</label><label class="checks"><input type="checkbox" name="summary" ${state.settings.summary?'checked':''}>פתיחה בלוח הניהולי</label></div></div><div class="form-actions"><button type="button" class="outline" data-action="cancel-settings">ביטול שינויים</button><button>שמירת העדפות</button></div></form></div>`;
}
